template:
fn add_suffix(s: ⟦param_ty⟧) {
    s.push_str("!");
}

fn main() {
    let mut msg = String::from("Hello");
    add_suffix(⟦arg⟧);
    println!("{msg}");
}

tests:
#[test]
fn mutates_string() {
    let mut msg = String::from("Hello");
    add_suffix(&mut msg);
    assert_eq!(msg, "Hello!");
}
